export interface SimpleListItemProps {
  children?: ReactNode;
  /** Right-aligned controls (buttons, switches, tags). */
  actions?: ReactNode[];
  onClick?: React.MouseEventHandler<HTMLDivElement>;
  className?: string;
  style?: CSSProperties;
}

function SimpleListItem({ children, actions, onClick, className, style }: SimpleListItemProps) {
  const { token } = theme.useToken();
  const size = useContext(SizeContext);
  const paddingBlock = size === 'small' ? token.paddingXS : token.paddingSM;
  const hasActions = !!actions && actions.length > 0;

  return (
    <div
      className={className}
      onClick={onClick}
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        // Actions never shrink, so without wrap the content region gets `container − actions` — a
        // char-per-line sliver on phone widths (#692).
        flexWrap: 'wrap',
        gap: token.padding,
        paddingBlock,
        // A caller-supplied style wins (e.g. the Suites master row overrides
        // padding + sets its own selected background).
        ...style,
      }}
    >
      {/* Mirror antd's List.Item: with actions, children live in a flex-1 "main"
          region and the actions sit right; without, the bare children are the
          flex items themselves and `space-between` spreads them (how a two-child
          row lands its label left / status right). */}
      {hasActions ? (
        <>
          {/* The min() floor is what makes the wrap trigger: with a bare
              minWidth:0 the content shrinks to a sliver before the actions
              ever wrap (#692). */}
          <div style={{ flex: '1 1 auto', minWidth: 'min(100%, 180px)' }}>{children}</div>
          <Flex
            align="center"
            gap={token.paddingSM}
            style={{ flexShrink: 0, marginInlineStart: 'auto' }}
          >
            {actions}
          </Flex>
